import java.util.Base64;
import java.util.List;
import java.util.UUID;

@Service
public class AuthService {

    private static final Logger logger = LoggerFactory.getLogger(AuthService.class);

    private static final SecureRandom secureRandom = new SecureRandom();

    private final TokenRepository tokenRepository;
    private final UserRepository userRepository;

    // Token lifetimes
    private static final long ACCESS_TOKEN_LIFETIME_SECONDS = 10 * 60; // 10 minutes
    private static final long REFRESH_TOKEN_LIFETIME_SECONDS = 24 * 60 * 60; // 24 hours
    private static final long ONE_TIME_TOKEN_LIFETIME_SECONDS = 5 * 60; // 5 minutes

    @Autowired
    public AuthService(TokenRepository tokenRepository, UserRepository userRepository) {
        this.tokenRepository = tokenRepository;
        this.userRepository = userRepository;
    }

    /**
     * Generate a secure random token string
     */
    private String generateToken() {
        String uuid = UUID.randomUUID().toString();
        // Add some random bytes to make it more secure
        byte[] randomBytes = new byte[16];
        secureRandom.nextBytes(randomBytes);
        String randomPart = Base64.getUrlEncoder().withoutPadding().encodeToString(randomBytes);
        return uuid + "_" + randomPart;
    }

    /**
     * Login endpoint - issue all three tokens atomically
     */
    @Transactional
    public LoginResponse login(LoginRequest request, HttpServletResponse response) {
        // Find or create user
        User user = userRepository.findByUsername(request.getUsername())
            .orElseGet(() -> {
                User newUser = new User();
                newUser.setUsername(request.getUsername());
                newUser.setPassword(request.getPassword());
                userRepository.save(newUser);
                return newUser;
            });

        // Generate tokens
        String accessToken = generateToken();
        String refreshToken = generateToken();
        String oneTimeToken = generateToken();

        Instant now = Instant.now();

        // Create Access Token (10 min)
        Token accessTokenEntity = new Token();
        accessTokenEntity.setTokenValue(accessToken);
        accessTokenEntity.setUserId(user.getId());
        accessTokenEntity.setTokenType(TokenType.ACCESS_TOKEN);
        accessTokenEntity.setIssuedAt(now);
        accessTokenEntity.setExpiresAt(now.plusSeconds(ACCESS_TOKEN_LIFETIME_SECONDS));
        accessTokenEntity.setRevoked(false);
        accessTokenEntity.setConsumed(false);
        tokenRepository.save(accessTokenEntity);

        // Create Refresh Token (24h)
        Token refreshTokenEntity = new Token();
        refreshTokenEntity.setTokenValue(refreshToken);
        refreshTokenEntity.setUserId(user.getId());
        refreshTokenEntity.setTokenType(TokenType.REFRESH_TOKEN);
        refreshTokenEntity.setIssuedAt(now);
        refreshTokenEntity.setExpiresAt(now.plusSeconds(REFRESH_TOKEN_LIFETIME_SECONDS));
        refreshTokenEntity.setRevoked(false);
        refreshTokenEntity.setConsumed(false);
        tokenRepository.save(refreshTokenEntity);

        // Create One-Time Token (5 min)
        Token oneTimeTokenEntity = new Token();
        oneTimeTokenEntity.setTokenValue(oneTimeToken);
        oneTimeTokenEntity.setUserId(user.getId());
        oneTimeTokenEntity.setTokenType(TokenType.ONE_TIME_TOKEN);
        oneTimeTokenEntity.setIssuedAt(now);
        oneTimeTokenEntity.setExpiresAt(now.plusSeconds(ONE_TIME_TOKEN_LIFETIME_SECONDS));
        oneTimeTokenEntity.setRevoked(false);
        oneTimeTokenEntity.setConsumed(false);
        tokenRepository.save(oneTimeTokenEntity);

        // Set refresh token as HTTP-only cookie
        Cookie cookie = new Cookie("refreshToken", refreshToken);
        cookie.setMaxAge(86400); // 24 hours in seconds
        cookie.setHttpOnly(true);
        cookie.setSecure(false); // For local development
        cookie.setPath("/");
        response.addCookie(cookie);

        LoginResponse responseDto = new LoginResponse();
        responseDto.setAccessToken(accessToken);
        responseDto.setOneTimeToken(oneTimeToken);

        return responseDto;
    }

    /**
     * Renew access token using refresh token with rotation
     * Must be atomic: revoke old refresh token, issue new refresh token and access token
     */
    @Transactional
    public String renewAccessToken(String refreshTokenValue, HttpServletResponse response) {
        // Find refresh token with pessimistic locking
        Token oldRefreshToken = tokenRepository.findTokenByValueLocking(refreshTokenValue)
            .orElseThrow(() -> new RuntimeException("Refresh token not found"));

        // Validate the refresh token
        if (oldRefreshToken.isRevoked()) {
            throw new RuntimeException("Refresh token has been revoked");
        }
        if (oldRefreshToken.isConsumed()) {
            throw new RuntimeException("Refresh token has been consumed");
        }
        if (oldRefreshToken.getExpiresAt().isBefore(Instant.now())) {
            throw new RuntimeException("Refresh token has expired");
        }

        // Get the user
        User user = userRepository.findById(oldRefreshToken.getUserId())
            .orElseThrow(() -> new RuntimeException("User not found"));

        // Revoke the old refresh token atomically (within same transaction)
        oldRefreshToken.setRevoked(true);
        tokenRepository.save(oldRefreshToken);

        // Generate new tokens
        String newAccessToken = generateToken();
        String newRefreshToken = generateToken();

        Instant now = Instant.now();

        // Create new Access Token (10 min)
        Token newAccessTokenEntity = new Token();
        newAccessTokenEntity.setTokenValue(newAccessToken);
        newAccessTokenEntity.setUserId(user.getId());
        newAccessTokenEntity.setTokenType(TokenType.ACCESS_TOKEN);
        newAccessTokenEntity.setIssuedAt(now);
        newAccessTokenEntity.setExpiresAt(now.plusSeconds(ACCESS_TOKEN_LIFETIME_SECONDS));
        newAccessTokenEntity.setRevoked(false);
        newAccessTokenEntity.setConsumed(false);
        tokenRepository.save(newAccessTokenEntity);

        // Create new Refresh Token (24h)
        Token newRefreshTokenEntity = new Token();
        newRefreshTokenEntity.setTokenValue(newRefreshToken);
        newRefreshTokenEntity.setUserId(user.getId());
        newRefreshTokenEntity.setTokenType(TokenType.REFRESH_TOKEN);
        newRefreshTokenEntity.setIssuedAt(now);
        newRefreshTokenEntity.setExpiresAt(now.plusSeconds(REFRESH_TOKEN_LIFETIME_SECONDS));
        newRefreshTokenEntity.setRevoked(false);
        newRefreshTokenEntity.setConsumed(false);
        tokenRepository.save(newRefreshTokenEntity);

        // Set new refresh token as HTTP-only cookie
        Cookie cookie = new Cookie("refreshToken", newRefreshToken);
        cookie.setMaxAge(86400);
        cookie.setHttpOnly(true);
        cookie.setPath("/");
        response.addCookie(cookie);

        return newAccessToken;
    }

    /**
     * Validate and consume a one-time token
     */
    @Transactional
    public ValidateTokenResponse validateOneTimeToken(String tokenValue) {
        // Find token with pessimistic locking
        Token token = tokenRepository.findTokenByValueLocking(tokenValue)
            .orElseThrow(() -> new RuntimeException("Token not found"));

        // Check validity
        if (token.getTokenType() != TokenType.ONE_TIME_TOKEN) {
            return new ValidateTokenResponse();
        }
        if (token.getUserId() == null) {
            return new ValidateTokenResponse();
        }
        if (token.isRevoked()) {
            return new ValidateTokenResponse();
        }
        if (token.isConsumed()) {
            return new ValidateTokenResponse();
        }
        if (token.getExpiresAt().isBefore(Instant.now())) {
            return new ValidateTokenResponse();
        }

        // All checks passed - atomically mark as consumed
        token.setConsumed(true);
        tokenRepository.save(token);

        ValidateTokenResponse response = new ValidateTokenResponse();
        response.setValid(true);
        response.setMessage("Token is valid");
        return response;
    }

    /**
     * Logout - revoke all tokens for a user (by userId)
     */
    @Transactional
    public void logoutByUserId(Long userId) {
        // Find all tokens for this user and revoke them
        List<Token> tokens = tokenRepository.findByUserId(userId);
        for (Token token : tokens) {
            token.setRevoked(true);
            tokenRepository.save(token);
        }
    }

    /**
     * Logout via access token - validate and revoke all user's tokens
     */
    @Transactional
    public void logout(String accessTokenValue) {
        // Find the access token to get the userId
        Token access_token = tokenRepository.findTokenByValueLocking(accessTokenValue)
            .orElseThrow(() -> new RuntimeException("Access token not found"));

        // Validate it's an access token and not already revoked/expired
        if (access_token.getTokenType() != TokenType.ACCESS_TOKEN) {
            throw new RuntimeException("Invalid token type");
        }
        if (access_token.isRevoked()) {
            throw new RuntimeException("Token has been revoked");
        }
        if (access_token.getExpiresAt().isBefore(Instant.now())) {
            throw new RuntimeException("Token has expired");
        }

        // Get userId and revoke all tokens for that user
        Long userId = access_token.getUserId();
        if (userId == null) {
            throw new RuntimeException("Invalid token");
        }

        // Revoke all tokens for this user
        List<Token> userTokens = tokenRepository.findByUserId(userId);
        for (Token token : userTokens) {
            token.setRevoked(true);
            tokenRepository.save(token);
        }
    }
}
EOF"}

