package com.example.auth.controller;

import com.example.auth.dto.LoginRequest;
import com.example.auth.dto.LoginResponse;
import com.example.auth.dto.ValidateTokenRequest;
import com.example.auth.dto.ValidateTokenResponse;
import com.example.auth.service.AuthService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import jakarta.servlet.http.Cookie;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;

import java.util.HashMap;
import java.util.Map;

@RestController
@RequestMapping("/api/auth")
public class AuthController {

    private static final Logger logger = LoggerFactory.getLogger(AuthController.class);

    private final AuthService authService;

    @Autowired
    public AuthController(AuthService authService) {
        this.authService = authService;
    }

    /**
     * Login endpoint
     */
    @PostMapping("/login")
    public ResponseEntity<LoginResponse> login(@RequestBody LoginRequest request, HttpServletResponse response) {
        try {
            // Validate request
            if (request.getUsername() == null || request.getUsername().isEmpty()) {
                return ResponseEntity.badRequest().build();
            }
            if (request.getPassword() == null || request.getPassword().isEmpty()) {
                return ResponseEntity.badRequest().build();
            }

            LoginResponse result = authService.login(request, response);
            return ResponseEntity.ok(result);
        } catch (Exception e) {
            logger.error("Login failed: {}", e.getMessage(), e);
            return ResponseEntity.status(400).build();
        }
    }

    /**
     * Renew access token endpoint
     */
    @PostMapping("/renew")
    public ResponseEntity<Map<String, String>> renew(HttpServletRequest request, HttpServletResponse response) {
        // Try to get refresh token from cookie first, then from header
        String refreshToken = null;

        // Check cookie
        Cookie[] cookies = request.getCookies();
        if (cookies != null) {
            for (Cookie cookie : cookies) {
                if ("refreshToken".equals(cookie.getName())) {
                    refreshToken = cookie.getValue();
                    break;
                }
            }
        }

        // If not in cookie, check header
        if (refreshToken == null) {
            refreshToken = request.getHeader("refreshToken");
        }

        if (refreshToken == null || refreshToken.isEmpty()) {
            Map<String, String> error = new HashMap<>();
            error.put("error", "Refresh token missing");
            return ResponseEntity.status(401).body(error);
        }

        try {
            String newAccessToken = authService.renewAccessToken(refreshToken, response);
            Map<String, String> responseMap = new HashMap<>();
            responseMap.put("accessToken", newAccessToken);
            return ResponseEntity.ok(responseMap);
        } catch (Exception e) {
            logger.error("Token renewal failed: {}", e.getMessage(), e);
            Map<String, String> error = new HashMap<>();
            error.put("error", e.getMessage());
            return ResponseEntity.status(401).body(error);
        }
    }

    /**
     * Logout endpoint
     */
    @PostMapping("/logout")
    public ResponseEntity<Map<String, String>> logout(HttpServletRequest request) {
        String authorization = request.getHeader("Authorization");
        if (authorization == null || !authorization.startsWith("Bearer ")) {
            Map<String, String> error = new HashMap<>();
            error.put("error", "Missing or invalid Authorization header");
            return ResponseEntity.status(401).body(error);
        }

        String accessToken = authorization.substring(7);
        if (accessToken == null || accessToken.isEmpty()) {
            Map<String, String> error = new HashMap<>();
            error.put("error", "Invalid token");
            return ResponseEntity.status(401).body(error);
        }

        try {
            authService.logout(accessToken);
            return ResponseEntity.ok(Map.of("message", "Logged out successfully"));
        } catch (Exception e) {
            logger.error("Logout failed: {}", e.getMessage(), e);
            Map<String, String> error = new HashMap<>();
            error.put("error", e.getMessage());
            return ResponseEntity.status(401).body(error);
        }
    }

    /**
     * Validate one-time token endpoint
     */
    @PostMapping("/validate-token")
    public ResponseEntity<ValidateTokenResponse> validateToken(@RequestBody ValidateTokenRequest request) {
        try {
            if (request.getToken() == null || request.getToken().isEmpty()) {
                ValidateTokenResponse response = new ValidateTokenResponse();
                response.setValid(false);
                response.setMessage("Token missing");
                return ResponseEntity.status(401).body(response);
            }

            ValidateTokenResponse result = authService.validateOneTimeToken(request.getToken());
            if (result.isValid()) {
                return ResponseEntity.ok(result);
            } else {
                // Token is invalid for some reason (expired, consumed, etc.)
                return ResponseEntity.status(401).body(result);
            }
        } catch (Exception e) {
            logger.error("Token validation failed: {}", e.getMessage(), e);
            ValidateTokenResponse response = new ValidateTokenResponse();
            response.setValid(false);
            response.setMessage(e.getMessage());
            return ResponseEntity.status(409).body(response);
        }
    }
}
EOF"}

