package com.example.auth.config;

import com.example.auth.repository.TokenRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.Configuration;
import org.springframework.scheduling.annotation.Scheduled;

import java.time.Instant;

@Configuration
public class ScheduledConfig {

    private static final Logger logger = LoggerFactory.getLogger(ScheduledConfig.class);

    private final TokenRepository tokenRepository;

    @Autowired
    public ScheduledConfig(TokenRepository tokenRepository) {
        this.tokenRepository = tokenRepository;
    }

    @Scheduled(fixedRate = 10000) // Every 10 seconds
    public void cleanupTokens() {
        Instant now = Instant.now();

        // Find all tokens that are expired, revoked, or consumed
        // We need to query for tokens where expiresAt < now OR isRevoked = true OR isConsumed = true
        // But we can't do complex OR in JPQL easily with parameters. Let me do it in batches or use a different approach.

        // Actually, let's query tokens that meet any of these criteria
        // First get expired tokens
        // Then get revoked tokens  
        // Then get consumed tokens
        // But this could get duplicates. Better to use a native query or delete based on conditions.

        // Alternative: use JPA Criteria API or find all tokens and filter
        // For simplicity, let's query for each condition separately and delete carefully.

        // Actually, the cleanest is to find tokens where:
        // (expiresAt < now) OR (isRevoked) OR (isConsumed)
        // We can use a native SQL query for this.

        // But JPA doesn't easily support OR with parameters in a simple way.
        // Let me use a different approach: load all tokens with these flags and delete them.
        // But that could be many tokens.

        // Better: use native query with delete
        String sql = "DELETE FROM tokens t WHERE t.expires_at < :now OR t.is_revoked = true OR t.is_consumed = true";

        // Actually, Spring Data JPA doesn't support native DELETE with parameters easily in this form.
        // Let me use a different strategy: query for tokens to delete, then delete them.

        // Query for expired tokens
        var expiredTokens = tokenRepository.findByExpiresBefore(now);
        // Query for revoked tokens  
        var revokedTokens = tokenRepository.findByIsRevokedTrue();
        // Query for consumed tokens
        var consumedTokens = tokenRepository.findByIsConsumedTrue();

        // Combine and deduplicate by ID
        java.util.Set<Long> idsToDelete = new java.util.HashSet<>();
        expiredTokens.forEach(t -> idsToDelete.add(t.getId()));
        revokedTokens.forEach(t -> idsToDelete.add(t.getId()));
        consumedTokens.forEach(t -> idsToDelete.add(t.getId()));

        if (!idsToDelete.isEmpty()) {
            tokenRepository.deleteAllById(idsToDelete);
            logger.info("[CLEANUP] Deleted {} tokens", idsToDelete.size());
        }
    }
}
