import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.Configuration;
import org.springframework.scheduling.annotation.Scheduled;

import java.time.Instant;

@Configuration
public class ScheduledConfig {

    private static final Logger logger = LoggerFactory.getLogger(ScheduledConfig.class);

    private final TokenRepository tokenRepository;

    @Autowired
    public ScheduledConfig(TokenRepository tokenRepository) {
        this.tokenRepository = tokenRepository;
    }

    @Scheduled(fixedRate = 10000) // Every 10 seconds
    public void cleanupTokens() {
        Instant now = Instant.now();

        // Delete tokens that are expired, revoked, or consumed
        // Using the batch delete method for efficiency
        int deletedCount = tokenRepository.deleteByExpiredOrRevokedOrConsumed(now);

        if (deletedCount > 0) {
            logger.info("[CLEANUP] Deleted {} tokens", deletedCount);
        }
    }
}

